create or replace function public.generate_order_installment_schedule(_order_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare o public.orders; item jsonb; plan text; n integer; base numeric; remainder numeric; i integer; due_date date; begin select * into o from public.orders where id=_order_id for update; if not found then raise exception 'Order not found'; end if; item:=coalesce(o.items->0,'{}'::jsonb); plan:=lower(coalesce(item->>'payment_plan',item->>'plan_type','')); if plan in ('','outright','full','cash','one-time','one_time') then return 0; end if; n:=nullif(regexp_replace(coalesce(item->>'months',item->>'installment_months',''),'[^0-9]','','g'),'')::integer; if coalesce(n,0)<=0 then n:=case when plan in ('1-3','3','3_months','3 months') then 3 when plan in ('4-6','6','6_months','6 months') then 6 when plan in ('7-12','12','12_months','12 months') then 12 else 0 end; end if; if n<=0 then return 0; end if; if exists(select 1 from public.order_installments where order_id=_order_id) then return (select count(*)::int from public.order_installments where order_id=_order_id); end if; base:=round(coalesce(o.total_amount,0)/n,2); remainder:=coalesce(o.total_amount,0)-(base*(n-1)); for i in 1..n loop due_date:=current_date + ((i-1)*30); insert into public.order_installments(order_id,installment_number,due_date,amount_due,amount_paid,balance,status) values(_order_id,i,due_date,case when i=n then remainder else base end,0,case when i=n then remainder else base end,'pending'); end loop; return n; end; $$; revoke all on function public.generate_order_installment_schedule(uuid) from public; grant execute on function public.generate_order_installment_schedule(uuid) to authenticated;
